<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\ApiClient;use App\Models\JobApplication;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;
class CommercialApiController extends Controller{public function clients(Request $request):JsonResponse{$company=$this->company($request);return response()->json(['data'=>ApiClient::where('company_id',$company->id)->get(['id','name','key_prefix','scopes','last_used_at','expires_at','active'])]);}public function createClient(Request $request):JsonResponse{$company=$this->company($request);$data=$request->validate(['name'=>['required','string','max:100'],'scopes'=>['required','array'],'scopes.*'=>['in:jobs:read,applications:read'],'expires_at'=>['nullable','date','after:now']]);$plain='erd_'.Str::random(48);$client=ApiClient::create([...$data,'company_id'=>$company->id,'created_by'=>$request->user()->id,'key_prefix'=>substr($plain,0,12),'key_hash'=>hash('sha256',$plain)]);return response()->json(['data'=>['client'=>$client,'key'=>$plain],'message'=>'Guarda esta clave; no volverá a mostrarse.'],201);}public function jobs(Request $request):JsonResponse{$client=$request->attributes->get('api_client');return response()->json(['data'=>$client->company->jobs()->latest()->paginate(50)]);}public function applications(Request $request):JsonResponse{$client=$request->attributes->get('api_client');return response()->json(['data'=>JobApplication::with('job:id,title,slug','user:id,name,email')->whereHas('job',fn($q)=>$q->where('company_id',$client->company_id))->latest()->paginate(50)]);}private function company(Request $request){abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->first();abort_unless($company,422);$role=$company->members()->whereKey($request->user()->id)->first()?->pivot->role;abort_unless(in_array($role,['owner','admin']),403);return$company;}}
